const STATE = require('STATE')
const statedb = STATE(__filename)
const { sdb, get } = statedb(fallback_module)

const home_page_header = require('home_page_header')
const action_buttons = require('action_buttons')
const transaction_list = require('transaction_list')
const total_wealth = require('total_wealth')
const lightning_buttons = require('lightning_buttons')
const wallet_button = require('wallet_button')
const light_page_header = require('light_page_header')
const light_tx_list = require('light_tx_list')
const io = require('ws_client')

module.exports = home_contents

async function home_contents(opts = {}) {
  const { id, sdb } = await get(opts.sid)
  const { drive } = sdb

  const on = { style: inject, data: ondata }

  const el = document.createElement('div')
  el.id = "home_contents"
  const shadow = el.attachShadow({ mode: 'closed' })

  shadow.innerHTML = `
    <div class="home-contents-container"></div>
    <style></style>
  `

  const style = shadow.querySelector('style')
  const container = shadow.querySelector('.home-contents-container')

  const subs = await sdb.watch(onbatch)

  // -------------------- Create components --------------------
  // Pass opts with wallet info for initial BTC view
  const headerOpts = { wallet: 'btc', amount: '0.9616' }
  const home_page_header_component = await home_page_header(subs[0], headerOpts)
  const action_buttons_component = await action_buttons(subs[1], home_protocol)
  const transaction_list_component = await transaction_list(subs[2])
  const total_wealth_component = await total_wealth(subs[3])
  const lightning_buttons_component = await lightning_buttons(subs[4], home_protocol)
  const wallet_button_component = await wallet_button(subs[5], home_protocol)
  const light_page_header_component = await light_page_header(subs[6])
  const light_tx_list_component = await light_tx_list(subs[7])

  // default view: BTC wallet components
  container.append(
    home_page_header_component,
    wallet_button_component,
    action_buttons_component,
    transaction_list_component,
    total_wealth_component
  )

  // Real data integration
  let currentBtc = 0
  let currentLn = 0
  let nodeAlias = ''

  const wait = {}

  function fetchNodeInfo() {
    io_call('lightning-getinfo', { nodeId: 'node4' }, (m) => {
      const info = m.data?.data
      if (info?.alias) {
        nodeAlias = info.alias
      }
    })
  }

  function fetchBalances() {
    io_call('get_btc_balance', {}, (m) => {
      currentBtc = m.data?.data?.btc || 0
      updateUI()
    })

    io_call('get_ln_balance', { userId: 'node4' }, (m) => {
      const d = m.data?.data
      if (d) {
        currentLn = d.btc || 0
      }
      updateUI()
    })
  }

  function fetchBtcTransactions() {
    io_call('list_btc_transactions', { count: 20, skip: 0 }, (m) => {
      const txs = m.data?.data
      if (!Array.isArray(txs)) return

      // Transform bitcoind listtransactions format to UI format
      const formatted = txs.map(tx => {
        const date = new Date(tx.time * 1000)
        const dateString = date.toISOString().split('T')[0]
        const ttime = date.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: true })
        const sign = tx.category === 'receive' ? '+' : '-'
        const tamount = `${sign}${Math.abs(tx.amount).toFixed(8)}`
        const tid = nodeAlias || tx.txid || tx.address || 'Unknown'

        return { tid, ttime, tamount, dateString, avatar: '' }
      })

      if (transaction_list_component._update) {
        transaction_list_component._update(formatted)
      }
    })
  }

  function fetchLnTransactions() {
    io_call('get_transaction_history', { userId: 'node4', limit: 20 }, (m) => {
      const history = m.data?.data
      if (!Array.isArray(history)) return

      // Filter for Lightning transactions only
      const lnTxs = history.filter(tx => tx.type === 'LN')

      // Transform unified history format to UI format
      const formatted = lnTxs.map(tx => {
        const date = new Date(tx.timestamp * 1000)
        const dateString = date.toISOString().split('T')[0]
        const ttime = date.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: true })
        const sign = tx.direction === 'IN' ? '+' : '-'
        const amountBtc = (tx.amount_msat / 1000 / 1e8)
        const tamount = `${sign}${amountBtc.toFixed(8)}`
        const tid = nodeAlias || tx.note || tx.id || 'Unknown'

        return { tid, ttime, tamount, dateString, avatar: '' }
      })

      if (light_tx_list_component._update) {
        light_tx_list_component._update(formatted)
      }
    })
  }

  function io_call(type, data, handler) {
    const head = io.send(type, data)
    const key = String(head)

    if (!wait[key]) wait[key] = []
    wait[key].push(handler)

    // Legacy backup handler
    const legacyKey = ['backend', 'frontend', head[2]].join(',')
    wait[legacyKey] = wait[key]
  }

  function updateUI() {
    const total = Number(currentBtc) + Number(currentLn)
    if (total_wealth_component._update) {
      total_wealth_component._update({ total, lightning: Number(currentLn), bitcoin: Number(currentBtc) })
    }
    if (home_page_header_component._update) {
      home_page_header_component._update({ wallet: 'btc', amount: currentBtc })
    }
    // Update light_page_header if it has _update method, though it wasn't explicitly needed yet
    if (light_page_header_component._update) {
      light_page_header_component._update({ wallet: 'lightning', amount: currentLn })
    }
    // Update switch_account dropdown with real balances
    if (wallet_button_component._update) {
      wallet_button_component._update({ btc: Number(currentBtc), lightning: Number(currentLn) })
    }
  }

  // Handle incoming global msgs or routed callbacks
  io.on.home_contents = (m) => {
    let causeKey = null
    if (m.refs && m.refs.cause) {
      causeKey = String(m.refs.cause)
    } else if (m.head) {
      causeKey = String(m.head)
    }

    if (causeKey && wait[causeKey]) {
      const handlers = wait[causeKey]
      delete wait[causeKey]
      if (m.refs && m.refs.cause && m.head) {
        delete wait[String(m.head)] //prevent memory leak
      }

      for (const handler of handlers) {
        if (typeof handler === 'function') handler(m)
      }
    }

    if (m.type === 'payment_received' || m.type === 'request_update') {
      fetchBalances()
      fetchBtcTransactions()
      fetchLnTransactions()
    }
  }

  // Initial fetch
  fetchNodeInfo()
  fetchBalances()
  fetchBtcTransactions()
  fetchLnTransactions()

  // Periodic refresh (10s)
  setInterval(() => {
    fetchBalances()
    fetchBtcTransactions()
    fetchLnTransactions()
  }, 10000)

  return el

  // -------------------- Protocol to handle child messages --------------------
  function home_protocol(sendToChild) {
    return async function (messageFromChild) {
      if (messageFromChild?.from === 'switch_account' && messageFromChild.type === 'switch') {
        const wallet = messageFromChild.data

        if (wallet === 'btc') {
          // Update header dynamically
          home_page_header_component._update?.({ wallet: 'btc', amount: currentBtc || '0.00' })

          // Re-append BTC view components
          container.replaceChildren(
            home_page_header_component,
            wallet_button_component,
            action_buttons_component,
            transaction_list_component,
            total_wealth_component
          )

        } else if (wallet === 'lightning') {
          // Update header dynamically
          if (light_page_header_component._update) {
            light_page_header_component._update({ wallet: 'lightning', amount: currentLn || '0.00' })
          }

          // Show Lightning buttons instead of BTC action buttons
          container.replaceChildren(
            light_page_header_component,
            wallet_button_component,
            lightning_buttons_component,
            light_tx_list_component,
            total_wealth_component
          )

        }
      }
    }
  }

  async function onbatch(batch) {
    for (const { type, paths } of batch) {
      const data = await Promise.all(paths.map(p => drive.get(p).then(f => f.raw)))
      const func = on[type] || fail
      await func(data, type)
    }
  }

  function inject(data) { style.textContent = data[0] }
  function ondata(data) { }
  function fail(data, type) { throw new Error('invalid message', { cause: { data, type } }) }
}

// ------------------ Fallback for STATE ------------------
function fallback_module() {
  return {
    api,
    _: {
      'home_page_header': { $: '' },
      'action_buttons': { $: '' },
      'transaction_list': { $: '' },
      'total_wealth': { $: '' },
      'lightning_buttons': { $: '' },
      'wallet_button': { $: '' },
      'light_page_header': { $: '' },
      'light_tx_list': { $: '' },
      'ws_client': { $: '' }
    }
  }

  function api(opts) {
    if (!opts) opts = {}
    if (!opts.value) opts.value = {}

    const home_page_header = {
      mapping: { style: 'style', data: 'data', icons: 'icons' },
      0: { wallet: 'btc', amount: '0.9616' }
    }
    const action_buttons = { mapping: { style: 'style', data: 'data' }, 0: { buttons: { wallet: 'btc' } } }
    const transaction_list = {
      mapping: { style: 'style', data: 'data' },
      0: {
        value: [
          { tid: 'Luis fedrick', ttime: '11:30 AM', tamount: '+0.02456', avatar: 'https://tse4.mm.bing.net/th/id/OIP.VIRWK2jj8b2cHBaymZC5AgHaHa?w=800&h=800&rs=1&pid=ImgDetMain&o=7&rm=3' },
          { tid: 'skdmf932ksdmf0234lsd', ttime: '02:15 PM', tamount: '+0.03271', avatar: '' },
          { tid: 'Mark Kevin', ttime: '03:45 PM', tamount: '-0.00421', avatar: 'https://tse4.mm.bing.net/th/id/OIP.VIRWK2jj8b2cHBaymZC5AgHaHa?w=800&h=800&rs=1&pid=ImgDetMain&o=7&rm=3' },
          { tid: 'yweuyiewe32eqw234lsd', ttime: '12:30 PM', tamount: '+0.00567', avatar: '' },
        ]
      }
    }
    const total_wealth = {
      mapping: { style: 'style', data: 'data', icons: 'icons' },
      0: { value: { total: 0.9862, usd: 1000, lightning: 0.02456, bitcoin: 0.96164 } }
    }
    const lightning_buttons = { mapping: { style: 'style', data: 'data' }, 0: { buttons: { wallet: 'lightning' } } }
    const wallet_button = { mapping: { style: 'style', data: 'data' }, 0: { buttons: { wallet: 'btc' } } }
    const light_page_header = {
      mapping: { style: 'style', data: 'data', icons: 'icons' },
      0: { wallet: 'lightning', amount: '0.0246' }
    }
    const light_tx_list = {
      mapping: { style: 'style', data: 'data' },
      0: {
        value: [
          { tid: 'skdmf932ksdmf0234lsd', ttime: '09:15 AM', tamount: '-0.00123', avatar: '' },
          { tid: 'yweuyiewe32eqw234lsd', ttime: '12:30 PM', tamount: '+0.00567', avatar: '' },
          { tid: 'skdmf932hiuo1h2oihio', ttime: '04:20 PM', tamount: '-0.00234', avatar: '' },
          { tid: 'yweuyiewe32eqw234lsd', ttime: '12:30 PM', tamount: '+0.00567', avatar: '' },
        ]
      }
    }
    const ws_client = {
      mapping: { style: 'style', data: 'data' },
      0: {}
    }

    return {
      drive: {
        'style/': {
          'home_contents.css': {
            '$ref': 'home_contents.css'
          }
        },
        'data/': {
          'opts.json': {
            raw: opts || {}
          }
        }
      },
      _: {
        home_page_header,
        action_buttons,
        transaction_list,
        total_wealth,
        lightning_buttons,
        wallet_button,
        light_page_header,
        light_tx_list,
        ws_client
      }
    }
  }
}